// Deterministic local HTTP doubles, no DB/Noita or successful admission grants.
// The same real auth owner refreshes while lifecycle durability/send is blocked.
use std::io::{Read as _,Write as _};
type AuthReply=Box<dyn Fn(Value,String)->Value+Send>;
fn auth_http(replies:Vec<AuthReply>)->(String,std::thread::JoinHandle<()>){
 let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let origin=format!("http://{}",listener.local_addr().unwrap());
 let worker=std::thread::spawn(move||{listener.set_nonblocking(true).unwrap();let mut workers=vec![];for reply in replies{
  let until=Instant::now()+Duration::from_secs(8);let socket=loop{match listener.accept(){Ok((s,_))=>break s,Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>{assert!(Instant::now()<until,"Missing deterministic unit HTTP request");std::thread::sleep(Duration::from_millis(2));},Err(e)=>panic!("{e}")}};
  workers.push(std::thread::spawn(move||{let mut socket=socket;socket.set_nonblocking(false).unwrap();socket.set_read_timeout(Some(Duration::from_secs(3))).unwrap();let mut head=vec![];let mut byte=[0];while !head.ends_with(b"\r\n\r\n"){socket.read_exact(&mut byte).unwrap();head.push(byte[0]);assert!(head.len()<8192);}let head=String::from_utf8(head).unwrap();let size=head.lines().find_map(|s|s.to_ascii_lowercase().strip_prefix("content-length:").and_then(|s|s.trim().parse::<usize>().ok())).unwrap();assert!(size<=65536);let mut body=vec![0;size];socket.read_exact(&mut body).unwrap();let q:Value=serde_json::from_slice(&body).unwrap();let mut response=reply(q.clone(),head);if response["error"].is_object()&&(q["prepare"].is_object()||q["reconcile"].is_object()){response["error"]["retryAfterMs"]=json!(2000);}for key in ["major","revision","serviceId","serviceEpoch","requestId"]{response[key]=q[key].clone();}let bytes=serde_json::to_vec(&response).unwrap();let _=write!(socket,"HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",bytes.len());let _=socket.write_all(&bytes);
  }));}for w in workers{w.join().unwrap();}});(origin,worker)
}
fn renewed_reply(d:Session,device:uuid::Uuid)->AuthReply{Box::new(move|q,_|{use base64::Engine;assert!(q["refresh"].is_object());let access=format!("fixture.{}.unsigned",base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(json!({"jti":"rollover-new"}).to_string()));json!({"credentials":{"accessToken":access,"refreshSecret":"r".repeat(43),"accountId":d.account,"sessionId":d.id,"sessionEpoch":d.epoch,"kind":"desktop","deviceId":device,"expiresAt":"2099-01-01T00:00:00Z","principal":d.principal},"credentialValidity":{"principalId":d.account,"sessionId":d.id,"sessionEpoch":d.epoch,"credentialId":"rollover-new","originRequestId":q["requestId"],"sampleKey":"c".repeat(64),"accessRemainingMs":900000}})})}
fn auth_origin(c:&mut Core<MemoryStore>,origin:&str){c.base=origin.into();for r in [&mut c.world.record,&mut c.world.draft].into_iter().flatten(){r.identity.origin=origin.into();r.identity.config_digest=nt2_desktop_g0::protocol_connection::canonical_fingerprint(&serde_json::to_vec(&r.config).unwrap()).unwrap();}}
fn call_request(c:&Core<MemoryStore>,prepare:bool)->w::Request{let d=c.desktop.as_ref().unwrap();let r=if prepare{c.world.draft.as_ref().unwrap()}else{c.world.record.as_ref().unwrap()};let mut q=envelope(&c.service,&c.epoch,d);if prepare{q.prepare=Some(w::PrepareWorld{world_id:Some(r.world.to_string()),room_id:Some(r.identity.room.clone()),proof:Some("p".repeat(43)),config_revision:Some(r.identity.config as u32),config_digest:Some(r.identity.config_digest.clone())});}else{q.reconcile=Some(w::Reconcile{association:Some(serde_json::from_value(r.association.clone().unwrap()).unwrap()),proof:Some("p".repeat(43)),attempt:Some(1),connection_id:Some(hex(&[1;16])),action:Some("connect".into()),game_version:Some("fixture".into()),mod_version:Some("fixture".into()),bridge_version:Some("fixture".into()),capabilities:Some(vec![]),..Default::default()});}q}
struct AuthDiskHold{release:Option<std::sync::mpsc::Sender<()>>,thread:Option<std::thread::JoinHandle<()>>}
impl AuthDiskHold{fn new(writer:Arc<Mutex<()>>)->Self{let(tx,rx)=std::sync::mpsc::channel();let(release,wait)=std::sync::mpsc::channel();let thread=std::thread::spawn(move||{let _guard=writer.lock().unwrap();tx.send(()).unwrap();let _=wait.recv_timeout(Duration::from_secs(8));});rx.recv_timeout(Duration::from_secs(2)).unwrap();Self{release:Some(release),thread:Some(thread)}}}
impl Drop for AuthDiskHold{fn drop(&mut self){if let Some(r)=self.release.take(){let _=r.send(());}if let Some(t)=self.thread.take(){t.join().unwrap();}}}
#[test]fn rollover_blocked_durability_reproduces_old_bearer_and_sends_current_for_both_operations(){tauri::async_runtime::block_on(async{
 for prepare in [true,false]{for legacy in [true,false]{let mut c=playing_preparation();let d=c.desktop.clone().unwrap();let old=d.access.as_str().to_owned();let(origin,server)=auth_http(vec![renewed_reply(d.clone(),c.device),Box::new(move|q,head|{assert!(if prepare{q["prepare"].is_object()}else{q["reconcile"].is_object()});let header=head.lines().find(|s|s.to_ascii_lowercase().starts_with("authorization:")).unwrap();json!({"error":{"code":if header.ends_with(&old){"UNAUTHENTICATED"}else{"ENTRY_NOT_STAGING"}}})})]);auth_origin(&mut c,&origin);let mut runner=c.auth_runner();let call=c.lc1_call(prepare).unwrap();let mut q=call_request(&c,prepare);call.bind(&mut q);let expected=serde_json::to_vec(&q).unwrap();let record=if prepare{c.world.draft.as_ref().unwrap().clone()}else{c.world.record.as_ref().unwrap().clone()};let hold=AuthDiskHold::new(c.credential_writer.clone());let files=c.world_files.clone();let writer=c.credential_writer.clone();let http=c.http.clone();let task_call=call.clone();let target=origin.clone();let worker=tokio::spawn(async move{save(files,writer,record).await.unwrap();if legacy{rpc(&http,&target,&d,&q).await}else{task_call.send(&http,&target,&q).await.map(|v|v.0)}});
  runner.pump().await.unwrap();assert_eq!(c.auth_owner.lock().unwrap().view(c.desktop.as_ref())["renewals"],1);assert!(!worker.is_finished(),"Network work escaped blocked durability");drop(hold);let error=worker.await.unwrap().unwrap_err();assert_eq!(error,if legacy{"UNAUTHENTICATED"}else{"ENTRY_NOT_STAGING"});assert_eq!(serde_json::to_vec(call.request_for_test().as_ref().unwrap()).unwrap(),expected);if !legacy{assert_eq!(call.view()["usedCredentialGeneration"],1);}server.join().unwrap();
 }}
});}
#[test]fn rollover_late_old_auth_error_preserves_lease_and_original_request(){tauri::async_runtime::block_on(async{
 for prepare in [true,false]{let mut c=playing_preparation();let d=c.desktop.clone().unwrap();let(seen_tx,seen_rx)=tokio::sync::oneshot::channel();let seen=Mutex::new(Some(seen_tx));let(release,wait)=std::sync::mpsc::channel();let wait=Mutex::new(wait);let(origin,server)=auth_http(vec![Box::new(move|_,_|{seen.lock().unwrap().take().unwrap().send(()).unwrap();wait.lock().unwrap().recv_timeout(Duration::from_secs(5)).unwrap();json!({"error":{"code":"UNAUTHENTICATED"}})}),renewed_reply(d,c.device)]);auth_origin(&mut c,&origin);let mut runner=c.auth_runner();let call=c.lc1_call(prepare).unwrap();let mut q=call_request(&c,prepare);call.bind(&mut q);let original=q.request_id.clone();let http=c.http.clone();let task_call=call.clone();let target=origin.clone();let worker=tokio::spawn(async move{task_call.send(&http,&target,&q).await.map(|_|()).unwrap_err()});seen_rx.await.unwrap();runner.pump().await.unwrap();c.sync_auth_owner();release.send(()).unwrap();let error=worker.await.unwrap();let before=c.pending.lock().unwrap().clone().unwrap();let next=c.world.next;
  if prepare{c.world.prepare_call=Some(call);c.world.prepare=Some(tokio::spawn(async move{Err(error)}));while !c.world.prepare.as_ref().unwrap().is_finished(){tokio::task::yield_now().await;}c.lc1_poll_prepare().await.unwrap();}else{c.world.network_call=Some(call);c.world.network=Some(tokio::spawn(async move{Err(error)}));while !c.world.network.as_ref().unwrap().is_finished(){tokio::task::yield_now().await;}c.lc1_poll_network().await.unwrap();}
  let after=c.pending.lock().unwrap().clone().unwrap();assert_eq!(after.release,before.release);assert_eq!(after.authority_until,before.authority_until);assert_eq!(after.observation.as_ref().unwrap().observed_at,before.observation.as_ref().unwrap().observed_at);assert_eq!(c.world.coordinator.stage(),Stage::Playing);assert_eq!(c.world.next,next);assert!(!c.auth_owner.lock().unwrap().fixture_refresh_requested());assert_eq!(c.world.credential_failure["disposition"],"stale-credential");let retry=c.lc1_call(prepare).unwrap();let mut same=call_request(&c,prepare);retry.bind(&mut same);assert_eq!(same.request_id,original,"Rollover changed the original request identity");server.join().unwrap();
 }
});}
#[test]fn rollover_current_auth_and_expired_errors_still_protect(){tauri::async_runtime::block_on(async{
 for prepare in [true,false]{for error in ["UNAUTHENTICATED","EXPIRED","FORBIDDEN"]{let mut c=playing_preparation();if prepare{c.world.record=None;}let(origin,server)=auth_http(vec![Box::new(move|_,_|json!({"error":{"code":error}}))]);auth_origin(&mut c,&origin);let call=c.lc1_call(prepare).unwrap();let mut q=call_request(&c,prepare);call.bind(&mut q);let failure=call.send(&c.http,&origin,&q).await.err().unwrap();if prepare{c.world.prepare_call=Some(call);c.world.prepare=Some(tokio::spawn(async move{Err(failure)}));while !c.world.prepare.as_ref().unwrap().is_finished(){tokio::task::yield_now().await;}}else{c.world.network_call=Some(call);c.world.network=Some(tokio::spawn(async move{Err(failure)}));while !c.world.network.as_ref().unwrap().is_finished(){tokio::task::yield_now().await;}}
  assert_eq!(c.lc1_tick().await.unwrap_err(),error);let p=c.pending.lock().unwrap();let p=p.as_ref().unwrap();assert!(!p.release&&p.authority_until<=Instant::now());assert_eq!(c.world.credential_failure["disposition"],"current-error");server.join().unwrap();
 }}
});}
#[test]fn rollover_retired_context_error_cannot_revoke_new_owner(){tauri::async_runtime::block_on(async{
 for prepare in [true,false]{let mut c=playing_preparation();let call=c.lc1_call(prepare).unwrap();let old=c.world.native.unwrap();let next=(old.0,[2;16]);c.world.native=Some(next);c.game.as_mut().unwrap().owner=next;let record=c.world.record.as_ref().unwrap();let ticket=c.world.coordinator.bind(record.world,next,record.sequence);{let mut p=c.pending.lock().unwrap();let p=p.as_mut().unwrap();p.owner=Some(next);c.world.coordinator.complete_until(&ticket,Stage::Playing,p.authority_until,p.observation.as_ref().unwrap().observed_at);}let until=c.pending.lock().unwrap().as_ref().unwrap().authority_until;
  if prepare{c.world.prepare_call=Some(call);c.world.prepare=Some(tokio::spawn(async{Err("UNAUTHENTICATED".into())}));while !c.world.prepare.as_ref().unwrap().is_finished(){tokio::task::yield_now().await;}c.lc1_poll_prepare().await.unwrap();}else{c.world.network_call=Some(call);c.world.network=Some(tokio::spawn(async{Err("UNAUTHENTICATED".into())}));while !c.world.network.as_ref().unwrap().is_finished(){tokio::task::yield_now().await;}c.lc1_poll_network().await.unwrap();}let p=c.pending.lock().unwrap();let p=p.as_ref().unwrap();assert_eq!(p.owner,Some(next));assert!(p.release);assert_eq!(p.authority_until,until);assert_eq!(c.world.coordinator.stage(),Stage::Playing);assert_eq!(c.world.credential_failure["disposition"],"retired-owner");
 }
});}
#[test]fn rollover_identity_change_is_rejected_before_send(){tauri::async_runtime::block_on(async{
 for changed in 0..5{let mut c=playing_preparation();let call=c.lc1_call(false).unwrap();let q=call_request(&c,false);match changed{0=>c.desktop.as_mut().unwrap().account="different".into(),1=>c.desktop.as_mut().unwrap().id="different".into(),2=>c.desktop.as_mut().unwrap().epoch="different".into(),3=>c.epoch="different".into(),_=>c.device=uuid::Uuid::new_v4()};c.publish_auth_owner();assert!(call.send(&c.http,&c.base,&q).await.is_err());assert!(call.view()["usedCredentialGeneration"].is_null(),"Retired identity reached HTTP");}
});}
#[test]fn rollover_newer_credentials_do_not_hide_expiry_authorization_storage_or_unknown_failure(){tauri::async_runtime::block_on(async{
 for prepare in [true,false]{for error in ["EXPIRED".to_owned(),"FORBIDDEN".to_owned(),"Lifecycle reply interrupted".to_owned(),format!("{}flush failed",nt2_desktop_g0::world_store::FAILURE_PREFIX)]{
  let mut c=playing_preparation();let d=c.desktop.clone().unwrap();let(origin,server)=auth_http(vec![Box::new(|_,_|json!({"error":{"code":"EXPIRED"}})),renewed_reply(d,c.device)]);auth_origin(&mut c,&origin);let mut runner=c.auth_runner();let call=c.lc1_call(prepare).unwrap();let mut q=call_request(&c,prepare);call.bind(&mut q);assert_eq!(call.send(&c.http,&origin,&q).await.err().unwrap(),"EXPIRED");runner.pump().await.unwrap();c.sync_auth_owner();assert!(!call.stale_auth(&error));if prepare{c.world.record=None;c.world.prepare_call=Some(call);let failure=error.clone();c.world.prepare=Some(tokio::spawn(async move{Err(failure)}));while !c.world.prepare.as_ref().unwrap().is_finished(){tokio::task::yield_now().await;}}else{c.world.network_call=Some(call);let failure=error.clone();c.world.network=Some(tokio::spawn(async move{Err(failure)}));while !c.world.network.as_ref().unwrap().is_finished(){tokio::task::yield_now().await;}}
  let before=c.pending.lock().unwrap().as_ref().unwrap().authority_until;assert_eq!(c.lc1_tick().await.unwrap_err(),error);{let p=c.pending.lock().unwrap();let p=p.as_ref().unwrap();if error=="Lifecycle reply interrupted"{assert!(p.release);assert_eq!(p.authority_until,before,"Unknown outcome extended authority");}else{assert!(!p.release,"Current {error} was hidden");}}assert_eq!(c.world.credential_failure["disposition"],"current-error");server.join().unwrap();
 }}
});}
#[test]fn rollover_retirement_during_durability_prevents_send_and_changed_command_keeps_new_identity(){tauri::async_runtime::block_on(async{
 for prepare in [true,false]{let mut c=playing_preparation();let call=c.lc1_call(prepare).unwrap();let mut q=call_request(&c,prepare);call.bind(&mut q);let original=q.request_id.clone();let mut changed=call_request(&c,prepare);if prepare{changed.prepare.as_mut().unwrap().proof=Some("q".repeat(43));}else{changed.reconcile.as_mut().unwrap().attempt=Some(2);}let changed_id=changed.request_id.clone();call.bind(&mut changed);assert_eq!(changed.request_id,changed_id);assert_ne!(changed.request_id,original);
  let record=if prepare{c.world.draft.as_ref().unwrap().clone()}else{c.world.record.as_ref().unwrap().clone()};let hold=AuthDiskHold::new(c.credential_writer.clone());let(files,writer,http,origin)=(c.world_files.clone(),c.credential_writer.clone(),c.http.clone(),c.base.clone());let task_call=call.clone();let worker=tokio::spawn(async move{save(files,writer,record).await.unwrap();task_call.send(&http,&origin,&q).await.map(|_|())});c.generation.fetch_add(1,Ordering::AcqRel);drop(hold);assert_eq!(worker.await.unwrap().unwrap_err(),"Lifecycle request context retired");assert!(call.view()["usedCredentialGeneration"].is_null());
 }
});}
